properties.query:
let alertWindow = 15m;
let binSize = 5m;
let fleetSizeGate = 8;
let alertVolumeGate = 5;
let fleetSignal =
    UAVFleetState_CL
    | where TimeGenerated > ago(alertWindow)
    | summarize MaxActiveUAVCount = max(ActiveUAVCount) by FleetId, bin(TimeGenerated, binSize)
    | where MaxActiveUAVCount >= fleetSizeGate
    | project TimeGenerated, SignalType = 'FleetSpike', Detail = FleetId, MetricValue = toreal(MaxActiveUAVCount);
let socSignal =
    SecurityAlert
    | where TimeGenerated > ago(alertWindow)
    | summarize AlertCount = count() by bin(TimeGenerated, binSize)
    | where AlertCount >= alertVolumeGate
    | project TimeGenerated, SignalType = 'SocOverload', Detail = 'SOC', MetricValue = toreal(AlertCount);
union fleetSignal, socSignal
| summarize Signals = make_set(SignalType), SignalCount = dcount(SignalType), MaxMetric = max(MetricValue) by bin(TimeGenerated, binSize)
| where SignalCount >= 2
| extend TriggerReason = strcat('군집포화_SOC과부하_동시신호_', tostring(Signals))
| extend Severity = 'High'
| project TimeGenerated, Signals, SignalCount, MaxMetric, TriggerReason, Severity
| order by TimeGenerated desc
